function parseDur(d){const p=d.split(':').map(Number);return p.length===3?p[0]*3600+p[1]*60+p[2]:p[0]*60+p[1]}
function fmt(s){return Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0')}
function playTrack(i,offset){musicIdx=i;const m=MUSIC[i];$('playerDock').classList.remove('hidden');$('dockTitle').textContent=m.t+' — Zazie Productions';$('dockCover').style.cssText=coverStyle(m,i);$('dockDur').textContent=m.dur;playSec=offset?offset*30:0;startAudio(m,i);isPlaying=true;$('dockPlay').textContent='⏸';startProgress(parseDur(m.dur));buildViz()}
function startAudio(m,i){try{const c=ac();stopGen();masterGain=c.createGain();masterGain.gain.value=.18;analyser=c.createAnalyser();analyser.fftSize=32;masterGain.connect(analyser);analyser.connect(c.destination);
const scales=[[110,130.8,164.8,196,246.9],[98,116.5,146.8,174.6,220],[87.3,103.8,138.6,155.5,207.6]];const sc=scales[i%3];let step=0;
const wave=['sine','triangle','sawtooth'][i%3];
genTimer=setInterval(()=>{if(!isPlaying)return;const f=sc[step%sc.length]*(step%7===6?2:1);const o=c.createOscillator(),g=c.createGain();o.type=wave;o.frequency.value=f;const t=c.currentTime;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.5,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+.5);o.connect(g).connect(masterGain);o.start(t);o.stop(t+.55);if(step%4===0)drum('kick');if(step%8===4)drum('hat');step++},320)}catch(e){}}
function stopGen(){if(genTimer){clearInterval(genTimer);genTimer=null}}
function startProgress(dur){clearInterval(playTimer);playTimer=setInterval(()=>{if(!isPlaying)return;playSec++;if(playSec>=dur){stepTrack(1);return}$('dockProg').style.width=(playSec/dur*100)+'%';$('dockTime').textContent=fmt(playSec);animViz()},1000)}
function buildViz(){$('dockViz').innerHTML=Array(16).fill(0).map(()=>'<div class="viz-bar" style="height:8px"></div>').join('')}
function animViz(){const bars=$('dockViz').children;let data=null;if(analyser){data=new Uint8Array(analyser.frequencyBinCount);analyser.getByteFrequencyData(data)}for(let b of bars){b.style.height=(data?(data[Math.floor(Math.random()*data.length)]/255*30+4):(Math.random()*28+4))+'px'}}
function togglePlay(){isPlaying=!isPlaying;$('dockPlay').textContent=isPlaying?'⏸':'▶';if(isPlaying&&!genTimer)startAudio(MUSIC[musicIdx],musicIdx)}
function stepTrack(d){playTrack((musicIdx+d+MUSIC.length)%MUSIC.length)}
function seek(e){const r=e.currentTarget.getBoundingClientRect();const dur=parseDur(MUSIC[musicIdx].dur);playSec=Math.floor((e.clientX-r.left)/r.width*dur)}
function closePlayer(){isPlaying=false;stopGen();clearInterval(playTimer);$('playerDock').classList.add('hidden')}

