document.addEventListener('keydown',e=>{const p=PADS.find(x=>x[2]===e.key);if(p&&document.activeElement.tagName!=='INPUT'&&document.activeElement.tagName!=='TEXTAREA')drum(p[1])});

/* ============ SIGNAL ROT ============ */
let rotOn=false,rotOsc=null,rotGain=null,rotFilter=null,rotLFO=null;
$('rotViz').innerHTML=Array(12).fill(0).map(()=>'<div class="viz-bar" style="height:6px"></div>').join('');
function toggleRot(){const c=ac();rotOn=!rotOn;$('rotPower').style.background=rotOn?'#e6ff4a':'';$('rotPower').style.color=rotOn?'#000':'';$('rotState').textContent=rotOn?'● ROTTING SIGNAL':'OFFLINE';$('rotState').style.color=rotOn?'#e6ff4a':'';
if(rotOn){rotOsc=c.createOscillator();rotOsc.type='sawtooth';rotOsc.frequency.value=55;rotFilter=c.createBiquadFilter();rotFilter.type='lowpass';rotGain=c.createGain();rotGain.gain.value=.12;rotLFO=c.createOscillator();rotLFO.frequency.value=2;const lg=c.createGain();lg.gain.value=200;rotLFO.connect(lg).connect(rotFilter.frequency);rotOsc.connect(rotFilter).connect(rotGain).connect(c.destination);rotOsc.start();rotLFO.start();updateRot();rotAnim()}else{try{rotOsc.stop();rotLFO.stop()}catch(e){}}}
function updateRot(){const d=+$('rotDecay').value,cr=+$('rotCrush').value,w=+$('rotWidth').value;$('rotDecayVal').textContent=d+'%';$('rotCrushVal').textContent=cr+'%';$('rotWidthVal').textContent=w+'%';if(rotOn&&rotFilter){rotFilter.frequency.value=4000-(d*35);rotOsc.frequency.value=55+(cr*.6);rotLFO.frequency.value=.5+w/12}}
function rotAnim(){if(!rotOn)return;[...$('rotViz').children].forEach(b=>b.style.height=(Math.random()*36+4)+'px');setTimeout(()=>requestAnimationFrame(rotAnim),140)}

