/* ============ REPOSITORY LAUNCH BAY ============ */
const LAUNCH={items:[],selected:null,loaded:false};
function launchEsc(value){return String(value==null?'':value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function launchDate(value){if(!value)return '—';const d=new Date(value);return isNaN(d.getTime())?'—':d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}
function launchBytes(bytes){if(!bytes&&bytes!==0)return '—';return bytes<1048576?(bytes/1024).toFixed(0)+' KB':(bytes/1048576).toFixed(1)+' MB'}
function renderLaunchBay(){
const host=$('launchBayBody');if(!host)return;
const snapshot=globalThis.ZMH_REPOS;
LAUNCH.items=snapshot&&Array.isArray(snapshot.repositories)?snapshot.repositories.filter(r=>r.embed||r.demoUrl):[];
if(!LAUNCH.items.length){
host.innerHTML='<div class="p-8 md:p-10 font-mono text-[11px] text-mute leading-relaxed">The repository snapshot is unavailable, so the live builds cannot be listed here. Open the <a href="repo.html" class="text-lime underline">repository atlas</a> or browse the <a href="https://github.com/zazieproductions" target="_blank" rel="noopener noreferrer" class="text-lime underline">GitHub account ↗</a>.</div>';
return;
}
if(!LAUNCH.selected||!LAUNCH.items.some(r=>r.id===LAUNCH.selected)){LAUNCH.selected=LAUNCH.items[0].id;LAUNCH.loaded=false}
const active=LAUNCH.items.find(r=>r.id===LAUNCH.selected);
const source=active.embed?active.embed.url:active.demoUrl;
const external=!active.embed;
const tabs=LAUNCH.items.map(r=>{const on=r.id===active.id;return '<button role="tab" aria-selected="'+on+'" onclick="launchBaySelect(\''+r.id+'\')" class="chip '+(on?'tab-active':'hover:border-lime')+'">'+launchEsc(r.displayName)+(r.embed?'':' <span class="opacity-60">EXT</span>')+'</button>'}).join('');
const stage=LAUNCH.loaded
?'<iframe id="launchBayFrame" src="'+source+'" title="'+launchEsc(active.displayName)+' — actual repository build" class="w-full block bg-[#05050a]" style="height:620px" loading="lazy" allow="autoplay; fullscreen; midi; microphone; clipboard-write; gamepad" referrerpolicy="no-referrer"></iframe>'
:'<div class="p-10 md:p-14 text-center"><div class="w-14 h-14 rounded-2xl bg-lime text-black flex items-center justify-center text-2xl font-bold mx-auto mb-4">▶</div><div class="font-bold text-2xl md:text-3xl">Run '+launchEsc(active.displayName)+' right here.</div><p class="text-mute text-sm max-w-xl mx-auto mt-3 leading-relaxed">'+(external?'This is the project’s own GitHub Pages deployment, embedded in the page.':'This is the project’s actual single-file build, copied verbatim from its repository and served from this site.')+' Some projects make sound — turn your volume down first.</p><button onclick="launchBayLoad()" class="btn-lime rounded-xl px-6 py-3 font-bold mt-6">LOAD THE ACTUAL APP</button></div>';
const meta=active.embed
?'FROM '+launchEsc(active.embed.sourcePath)+' · '+launchEsc(launchBytes(active.embed.bytes))+' · SYNCED '+launchEsc(launchDate(active.embed.syncedAt))
:'SERVED FROM '+launchEsc(new URL(source).host)+' · EXTERNAL DEPLOYMENT';
host.innerHTML='<div class="flex flex-wrap gap-2 p-3 border-b border-white/10 bg-black/30" role="tablist" aria-label="Runnable repository builds">'+tabs+'</div>'
+'<div class="relative bg-[#05050a]">'+stage+'</div>'
+'<div class="flex flex-wrap items-center justify-between gap-3 p-4 border-t border-white/10">'
+'<div class="font-mono text-[10px] text-mute leading-relaxed">'+(active.embed?'SOURCE-SYNCED BUILD':'EXTERNAL LIVE APP')+' · '+meta+'</div>'
+'<div class="flex flex-wrap gap-2"><button onclick="launchBayLoad()" class="chip hover:border-lime">RELOAD</button><a href="'+source+'" target="_blank" rel="noopener noreferrer" class="btn-ghost rounded-lg px-3 py-2 font-mono text-[10px]">OPEN STANDALONE ↗</a><a href="repo.html?id='+active.id+'#live" class="btn-lime rounded-lg px-3 py-2 font-mono text-[10px] font-bold">FULL DOSSIER →</a></div>'
+'</div>';
}
function launchBaySelect(id){LAUNCH.selected=id;LAUNCH.loaded=true;renderLaunchBay()}
function launchBayLoad(){LAUNCH.loaded=true;renderLaunchBay()}
function renderLaunchFallback(){
const host=$('launchBayBody');if(!host)return;
host.innerHTML='<div class="p-8 md:p-10 font-mono text-[11px] text-mute leading-relaxed">The repository snapshot could not be loaded. <a href="repo.html" class="text-lime underline">Open the repository atlas</a> to read the real READMEs, file trees and commits.</div>';
}
function loadRepoSnapshot(){
fetch('data/repos.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(data=>{
if(!data||!Array.isArray(data.repositories)||!data.repositories.length)throw new Error('empty snapshot');
globalThis.ZMH_REPOS=data;
renderCodeHoldings();
renderLaunchBay();
const stamp=$('repoSyncStamp');
if(stamp){stamp.textContent='SNAPSHOT '+new Date(data.generatedAt).toLocaleDateString('en-US',{day:'2-digit',month:'short',year:'numeric'}).toUpperCase()+' · '+data.counts.curated+' REPOS · '+data.counts.embedded+' EMBEDDED'}
}).catch(()=>{renderLaunchFallback();const stamp=$('repoSyncStamp');if(stamp)stamp.textContent='SNAPSHOT UNAVAILABLE'});
}
loadRepoSnapshot();
